import{_ as a}from"./chunks/EP.01-amis-quickstart.Dfyx3V7N.js";import{_ as o,o as c,c as t,a2 as d}from"./chunks/framework.CnJ-JtFX.js";const f=JSON.parse('{"title":"EP.01 半天搭完 CRUD，协议先对齐","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.01-amis-quickstart.md","filePath":"comics/EP.01-amis-quickstart.md","lastUpdated":1792683644000}'),r={name:"comics/EP.01-amis-quickstart.md"};function i(s,e,l,h,m,n){return c(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-01-半天搭完-crud-协议先对齐" tabindex="-1">EP.01 半天搭完 CRUD，协议先对齐 <a class="header-anchor" href="#ep-01-半天搭完-crud-协议先对齐" aria-label="Permalink to &quot;EP.01 半天搭完 CRUD，协议先对齐&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/01-amis-quickstart">guide/01-amis-quickstart</a></p></blockquote><p><img src="'+a+'" alt="EP.01 漫画"></p><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：运营要三十个后台页面，研发只有两个人；手写一个页面两天，交付后文案再改八轮，前端一直在排队。</li><li><strong>揭秘</strong>：码叔指出重复的不是业务，而是页面结构；amis 用一棵 JSON 树描述 <code>page</code>、<code>crud</code>、<code>filter</code>、<code>columns</code>，结构交给 Schema，数据交给 <code>fetcher</code>。</li><li><strong>实证</strong>：像素酱给出正确顺序——先定字段、状态与响应结构，再写 Schema，最后用增删改查四条链路验收。</li><li><strong>结案</strong>：码叔强调先跑通最小闭环，再谈批量、导出与权限；响应里缺 <code>status</code>，表格会以空白的方式失败。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-被浪费的是结构编写时间" tabindex="-1">第一格：被浪费的是结构编写时间 <a class="header-anchor" href="#第一格-被浪费的是结构编写时间" aria-label="Permalink to &quot;第一格：被浪费的是结构编写时间&quot;">​</a></h3><p>一个标准 CRUD 页面包含表格、筛选、分页、弹窗、表单校验、请求封装、错误提示与加载态。业务不同，这些结构的形状却高度相似。手写的问题不是「写不出来」，而是「每次都要重写一遍，且细节不一致」。</p><p>amis 的切入点就是这部分重复结构。它不替代业务代码，也不负责后端，只把页面的「骨架」抽象成 JSON。理解这个边界，才不会期待它顺手解决权限、审批流和数据建模。</p><p>对应正文：<a href="./../guide/01-amis-quickstart">从一个真实问题说起</a>。</p><h3 id="第二格-schema-是一棵树" tabindex="-1">第二格：Schema 是一棵树 <a class="header-anchor" href="#第二格-schema-是一棵树" aria-label="Permalink to &quot;第二格：Schema 是一棵树&quot;">​</a></h3><p><code>page</code> 是最外层容器，<code>crud</code> 是组合渲染器，它内部再拆成 <code>api</code>、<code>filter</code>、<code>columns</code>、<code>headerToolbar</code> 四个插槽。你写的不是「一个表格组件」，而是一份页面结构描述。</p><p>数据边界由 <code>env.fetcher</code> 提供。amis 只规定请求配置和响应形状，不绑定 axios 或 fetch。这样 Schema 可以在测试环境接内存 fetcher，在生产环境接真实请求，页面配置不用改。</p><h3 id="第三格-先定协议-再写-schema" tabindex="-1">第三格：先定协议，再写 Schema <a class="header-anchor" href="#第三格-先定协议-再写-schema" aria-label="Permalink to &quot;第三格：先定协议，再写 Schema&quot;">​</a></h3><p>漫画里的四步顺序值得抄下来：</p><ol><li>定字段：<code>orderNo</code>、<code>customer</code>、<code>amount</code>、<code>status</code>、<code>createdAt</code>；</li><li>定响应：<code>{ status: 0, data: { items, total } }</code>；</li><li>写 Schema：<code>crud</code> + <code>filter</code> + 弹窗表单 + 操作列；</li><li>验收：新增、编辑、删除、查询四条链路都能走通。</li></ol><p>顺序反了，常见后果是 Schema 写完才发现字段名对不上，然后同时改 Schema、fetcher 和后端，返工翻倍。</p><h3 id="第四格-最小闭环优先" tabindex="-1">第四格：最小闭环优先 <a class="header-anchor" href="#第四格-最小闭环优先" aria-label="Permalink to &quot;第四格：最小闭环优先&quot;">​</a></h3><p>第一个版本不需要批量导入、导出 Excel、权限控制。先把「能查、能增、能改、能删」跑通，再按需求加功能。每加一个功能，都回到同一个验收清单：数据是否刷新、错误是否提示、分页是否还正确。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>响应缺 <code>status</code></strong>：amis 认为请求失败，表格空白但不一定报错。</li><li><strong>列表字段不叫 <code>items</code> / <code>total</code></strong>：<code>crud</code> 拿不到数据，需要 <code>adaptor</code> 转换。</li><li><strong>忘记 <code>primaryField</code></strong>：编辑和删除无法定位行，翻页后必错。</li><li><strong>表达式写复杂业务</strong>：显隐和禁用适合表达式，多字段计算与异步校验不适合。</li><li><strong>用 <code>latest</code> 安装</strong>：amis 小版本之间也可能有 Schema 差异，锁定精确版本。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. amis 的 `crud` 为什么不是普通表格组件？</b></summary><p>因为它是组合渲染器：内部创建数据域、发起列表请求、渲染筛选表单、表格、分页与批量操作。Schema 里的 <code>api</code>、<code>filter</code>、<code>columns</code>、<code>headerToolbar</code> 分别对应数据、查询、展示、操作四个插槽。理解这一点，才能知道字段该写在哪一层。</p></details><details><summary><b>2. 为什么 fetcher 的返回值必须包含 `status` 与 `data`？</b></summary><p>amis 按 <code>{ status, msg, data }</code> 判断请求是否成功，并从 <code>data</code> 里取列表。缺少 <code>status</code> 时可能被当成失败；缺少 <code>data</code> 时列表为空。真实后端字段不同，应该在 <code>adaptor</code> 里转换，而不是改 Schema 去迁就接口。</p></details><details><summary><b>3. 第一个 CRUD 页面应该先做哪些功能？</b></summary><p>先做查询、分页、新增、编辑、删除五件事，并保证写操作后列表自动刷新。批量操作、导出、权限、审批流都放在最小闭环之后。每加一个功能都用同一套验收动作回归，避免「功能加了、基础链路坏了」。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/01-amis-quickstart">第 01 章正文</a></li><li><a href="./../guide/02-amis-advanced">第 02 章 · amis 进阶</a></li><li><a href="./../appendix/glossary">术语表</a></li></ul>',27)])])}const b=o(r,[["render",i]]);export{f as __pageData,b as default};
